//! Compile-time embedded catalogs, generated by `build.rs`.
//!
//! Exposes every catalog file as `(locale, domain, json)` plus the sorted
//! key table of the source (`en`) locale — the compile-time contract the
//! `t!` macro enforces: a key that is not here cannot be translated.

include!(concat!(env!("OUT_DIR"), "/generated_catalogs.rs"));

#[cfg(test)]
mod tests {
    use super::{CATALOG_FILES, KNOWN_KEYS, SHIPPED_LOCALES, is_known_key};

    #[test]
    fn en_is_the_source_locale_and_catalogs_are_embedded() {
        assert!(SHIPPED_LOCALES.contains(&"en"));
        assert!(
            CATALOG_FILES
                .iter()
                .any(|(l, d, _)| *l == "en" && *d == "errors")
        );
        assert!(!KNOWN_KEYS.is_empty());
        assert!(KNOWN_KEYS.windows(2).all(|pair| pair[0] < pair[1]));
    }

    #[test]
    fn known_keys_covers_the_error_titles() {
        assert!(is_known_key("errors.title.bad-request"));
        assert!(is_known_key("emails.invitation.subject"));
        assert!(!is_known_key("no.such.key"));
    }

    #[test]
    fn every_embedded_catalog_is_valid_json() {
        for (locale, domain, content) in CATALOG_FILES {
            let map: serde_json::Map<String, serde_json::Value> = serde_json::from_str(content)
                .unwrap_or_else(|err| panic!("catalog {locale}/{domain} is not valid JSON: {err}"));
            assert!(!map.is_empty(), "{locale}/{domain} catalog is empty");
        }
    }
}
